manifest.data:
{
  "id": "/",
  "name": "The Visual Edit",
  "short_name": "Visual Edit",
  "description": "An editorial directory for visual research and moodboarding.",
  "lang": "en",
  "start_url": "/",
  "scope": "/",
  "display": "standalone",
  "background_color": "#f4f0e8",
  "theme_color": "#302923",
  "icons": [
    {
      "src": "/icons/icon-192.png",
      "sizes": "192x192",
      "type": "image/png",
      "purpose": "any"
    },
    {
      "src": "/icons/icon-512.png",
      "sizes": "512x512",
      "type": "image/png",
      "purpose": "any"
    },
    {
      "src": "/icons/maskable-512.png",
      "sizes": "512x512",
      "type": "image/png",
      "purpose": "maskable"
    }
  ],
  "shortcuts": [
    {
      "name": "Source directory",
      "url": "/#directory"
    },
    {
      "name": "Browse countries",
      "url": "/#asia-browse"
    }
  ]
}
